/**
 * Every live issue of one project in number order, each with its label ids.
 * Deliberately unpaged: a clone walks the whole project, however large it is.
 */
export async function listAllLiveIssues(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Issue[]> {
  const db = getDb();
  const scope = and(
    ...compact(
      orgPredicate(issues.orgId, orgId),
      eq(issues.projectId, projectId),
      livePredicate(issues.archivedAt, {}),
    ),
  );

  const rows = db
    .select()
    .from(issues)
    .where(scope)
    .orderBy(asc(issues.number))
    .all();

  const links = db
    .select({ issueId: issueLabels.issueId, labelId: issueLabels.labelId })
    .from(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        inArray(
          issueLabels.issueId,
          db.select({ id: issues.id }).from(issues).where(scope),
        ),
      ),
    )
    .all();

  const labelIdsByIssue = new Map<string, LabelId[]>();
  for (const link of links) {
    const labelIds = labelIdsByIssue.get(link.issueId) ?? [];
    labelIds.push(brandId<LabelId>(link.labelId));
    labelIdsByIssue.set(link.issueId, labelIds);
  }

  return rows.map((row) => toIssue(row, labelIdsByIssue.get(row.id) ?? []));
}

