/**
 * Writes a clone and its copied issues in one transaction. The project row goes
 * first, so a duplicate key is refused before any copy exists. Copies take
 * numbers 1..n in the order given, start unassigned with no progress, and are
 * authored by `authorId`; only their labels come along.
 */
export async function insertClone(
  input: CreateProjectInput,
  copies: readonly Pick<
    Issue,
    "title" | "description" | "status" | "priority" | "estimate" | "dueAt" | "labelIds"
  >[],
  authorId: UserId,
): Promise<Project> {
  const projectId = newId();
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const row = tx
      .insert(projects)
      .values({
        id: projectId,
        orgId: input.orgId,
        name: input.name,
        slug: input.slug,
        key: input.key,
        description: input.description,
        visibility: input.visibility,
        status: "active",
        leadId: input.leadId,
        color: input.color,
        startsAt: null,
        targetDate: input.targetDate,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    copies.forEach((copy, index) => {
      const issueId = newId();
      tx.insert(issues)
        .values({
          id: issueId,
          orgId: input.orgId,
          projectId,
          number: index + 1,
          title: copy.title,
          description: copy.description,
          status: copy.status,
          priority: copy.priority,
          authorId,
          assigneeId: null,
          parentId: null,
          estimate: copy.estimate,
          dueAt: copy.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();

      if (copy.labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            copy.labelIds.map((labelId) => ({
              orgId: input.orgId,
              issueId,
              labelId,
            })),
          )
          .run();
      }
    });

    return toProject(row);
  });
}

