/**
 * Clones a project into the same workspace under the caller's name, slug and
 * key (ADR 0012). Gated like a creation: the source must be readable and live,
 * the caller must be able to create a project, and the plan's project quota
 * applies. The copies are checked against the per-project issue quota as one
 * batch before anything is written. Comments, attachments and links are not
 * copied, and the source is left untouched.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertCan(actor, "project:create", orgResource(input.orgId));
  assertNotArchived("Project", source.id, source);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const projectsUsed = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", projectsUsed)) {
    throw new Error(
      `Plan ${org.plan} allows ${projectsUsed} projects; upgrade to add another`,
    );
  }

  const sourceIssues = input.includeIssues
    ? await issueRepo.listAllLiveIssues(input.orgId, source.id)
    : [];
  if (wouldExceedLimit(org.plan, "issuesPerProject", 0, sourceIssues.length)) {
    throw new Error(
      `Plan ${org.plan} allows ${getLimit(org.plan, "issuesPerProject")} issues per project; cloning ${source.key} would copy ${sourceIssues.length}`,
    );
  }

  // Every copy starts as fresh work in the workspace's default status.
  const storedStatus = issueStatusSchema.safeParse(org.settings.defaultIssueStatus);
  const status = storedStatus.success ? storedStatus.data : "backlog";

  const copies = sourceIssues.map((issue) => ({
    title: issue.title,
    description: issue.description,
    status,
    priority: issue.priority,
    estimate: issue.estimate,
    dueAt: issue.dueAt,
    labelIds: issue.labelIds,
  }));

  const slug = uniqueSlug(
    input.slug,
    await projectRepo.listTakenProjectSlugs(input.orgId),
  );

  const clone = await projectRepo.insertClone(
    {
      orgId: input.orgId,
      name: input.name,
      slug,
      key: input.key,
      description: source.description,
      visibility: source.visibility,
      leadId: source.leadId,
      color: source.color,
      targetDate: null,
    },
    copies,
    actor.userId,
  );

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: clone.id,
    sourceProjectId: source.id,
    issuesCopied: copies.length,
  });

  return clone;
