/**
 * Cloning a project (ADR 0012): the gates, what a copy keeps and what it resets,
 * the batch quota, and the one event and audit row a clone publishes.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { activityFilterSchema } from "@/schemas/activity";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as activityService from "@/server/services/activity-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import * as usageService from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CloneProjectInput } from "@/schemas/project";
import type { ProjectId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

function cloneInput(
  tenant: Tenant,
  overrides: Partial<CloneProjectInput> = {},
): CloneProjectInput {
  return {
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    name: "Release train",
    slug: "release-train",
    key: "REL",
    includeIssues: true,
    ...overrides,
  };
}

/** Inserts issues through the repository, bypassing the quota, to build big projects. */
async function addIssues(tenant: Tenant, projectId: ProjectId, count: number): Promise<void> {
  for (let n = 1; n <= count; n += 1) {
    const number = await issueRepo.nextIssueNumber(tenant.org.id, projectId);
    await issueRepo.insertIssue(
      issueInput(tenant.org.id, projectId, { title: `Bulk issue ${n}` }),
      tenant.userIds.member,
      number,
    );
  }
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachers.push(
    activityService.registerActivityListeners(),
    usageService.registerUsageListeners(),
    searchService.registerSearchListeners(),
  );
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

describe("services/project-service cloneProject", () => {
  it("copies live issues as fresh work and leaves the source as it was", async () => {
    const tenant = await createTenant("clonecopy", "growth");
    const { org, project: source, actors, userIds } = tenant;

    const label = await labelRepo.insertLabel({
      orgId: org.id,
      name: "Clone bug",
      color: "#ff0000",
      description: null,
    });

    const alpha = await issueService.createIssue(actors.member, {
      ...issueInput(org.id, source.id, {
        title: "Alpha release",
        assigneeId: userIds.admin,
        dueAt: "2026-06-01T00:00:00.000Z",
      }),
      priority: "high",
      estimate: 3,
    });
    await labelRepo.setIssueLabels(org.id, alpha.id, [label.id]);
    await issueService.changeIssueStatus(actors.member, {
      orgId: org.id,
      issueId: alpha.id,
      status: "in_progress",
    });
    await commentService.createComment(actors.member, {
