import type { Tenant } from "../server/_support/fixtures";
import type { CloneProjectInput } from "@/schemas/project";
import type { ProjectId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

function cloneInput(
  tenant: Tenant,
  overrides: Partial<CloneProjectInput> = {},
): CloneProjectInput {
  return {
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    name: "Release train",
    slug: "release-train",
    key: "REL",
    includeIssues: true,
    ...overrides,
  };
}

/** Inserts issues through the repository, bypassing the quota, to build big projects. */
async function addIssues(tenant: Tenant, projectId: ProjectId, count: number): Promise<void> {
  for (let n = 1; n <= count; n += 1) {
    const number = await issueRepo.nextIssueNumber(tenant.org.id, projectId);
    await issueRepo.insertIssue(
      issueInput(tenant.org.id, projectId, { title: `Bulk issue ${n}` }),
      tenant.userIds.member,
      number,
    );
  }
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachers.push(
    activityService.registerActivityListeners(),
    usageService.registerUsageListeners(),
    searchService.registerSearchListeners(),
  );
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

describe("services/project-service cloneProject", () => {
  it("copies live issues as fresh work and leaves the source as it was", async () => {
    const tenant = await createTenant("clonecopy", "growth");
    const { org, project: source, actors, userIds } = tenant;

    const label = await labelRepo.insertLabel({
      orgId: org.id,
      name: "Clone bug",
      color: "#ff0000",
      description: null,
    });

    const alpha = await issueService.createIssue(actors.member, {
      ...issueInput(org.id, source.id, {
        title: "Alpha release",
        assigneeId: userIds.admin,
        dueAt: "2026-06-01T00:00:00.000Z",
      }),
      priority: "high",
      estimate: 3,
    });
    await labelRepo.setIssueLabels(org.id, alpha.id, [label.id]);
    await issueService.changeIssueStatus(actors.member, {
      orgId: org.id,
      issueId: alpha.id,
      status: "in_progress",
    });
    await commentService.createComment(actors.member, {
      orgId: org.id,
      issueId: alpha.id,
      body: "Pinned to the old plan",
      parentId: null,
      mentionedUserIds: [],
    });

    const gamma = await issueService.createIssue(
      actors.member,
      issueInput(org.id, source.id, { title: "Gamma wrap-up" }),
    );
    await issueService.changeIssueStatus(actors.member, {
      orgId: org.id,
      issueId: gamma.id,
      status: "done",
    });

    const old = await issueService.createIssue(
      actors.member,
      issueInput(org.id, source.id, { title: "Old and archived" }),
    );
    await issueService.archiveIssue(actors.member, org.id, old.id);

    const sourceBefore = await issueRepo.listAllLiveIssues(org.id, source.id);

    const clone = await projectService.cloneProject(actors.member, cloneInput(tenant));

    expect(clone.id).not.toBe(source.id);
    expect(clone).toMatchObject({
      orgId: org.id,
      name: "Release train",
      slug: "release-train",
      key: "REL",
      description: source.description,
      visibility: source.visibility,
      leadId: source.leadId,
      color: source.color,
      status: "active",
      targetDate: null,
      archivedAt: null,
    });

    const copies = await issueRepo.listAllLiveIssues(org.id, clone.id);
    expect(copies.map((issue) => [issue.number, issue.title])).toEqual([
      [1, "Alpha release"],
      [2, "Gamma wrap-up"],
    ]);

    const alphaCopy = copies.find((issue) => issue.title === "Alpha release");
    expect(alphaCopy).toMatchObject({
      projectId: clone.id,
      priority: "high",
      estimate: 3,
      dueAt: "2026-06-01T00:00:00.000Z",
      status: "backlog",
      assigneeId: null,
      authorId: userIds.member,
      startedAt: null,
      completedAt: null,
      parentId: null,
      labelIds: [label.id],
    });
    expect(alphaCopy && (await commentRepo.countComments(org.id, alphaCopy.id))).toBe(0);

    expect(copies.find((issue) => issue.title === "Gamma wrap-up")).toMatchObject({
      status: "backlog",
      completedAt: null,
    });

    expect(await issueRepo.listAllLiveIssues(org.id, source.id)).toEqual(sourceBefore);
  });

  it("publishes one project.cloned and no per-copy announcements", async () => {
    const tenant = await createTenant("cloneevents", "growth");
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Announce one" }),
    );
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Announce two" }),
    );

    const cloned = capture("project.cloned");
    const created = capture("project.created");
    const issueCreated = capture("issue.created");
    const usageBefore = await usageRepo.getUsage(tenant.org.id);

    const clone = await projectService.cloneProject(tenant.actors.admin, cloneInput(tenant));

    expect(cloned).toEqual([
      expect.objectContaining({
        orgId: tenant.org.id,
        actorId: tenant.userIds.admin,
        projectId: clone.id,
        sourceProjectId: tenant.project.id,
        issuesCopied: 2,
      }),
    ]);
    expect(created).toHaveLength(0);
    expect(issueCreated).toHaveLength(0);

    const usageAfter = await usageRepo.getUsage(tenant.org.id);
    expect(usageAfter.projectsUsed).toBe(usageBefore.projectsUsed + 1);
    expect(usageAfter.issuesUsed).toBe(usageBefore.issuesUsed + 2);
  });

  it("writes one audit row under the new project", async () => {
    const tenant = await createTenant("cloneaudit", "growth");
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Audited copy" }),
    );

    const clone = await projectService.cloneProject(tenant.actors.admin, cloneInput(tenant));

    const page = await activityService.listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["project.cloned"],
      limit: 25,
      cursor: null,
    });

    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      action: "project.cloned",
      actorId: tenant.userIds.admin,
      subjectKind: "project",
      subjectId: clone.id,
      projectId: clone.id,
      metadata: { sourceProjectId: tenant.project.id, issuesCopied: 1 },
    });
  });

  it("copies only the project when includeIssues is false", async () => {
    const tenant = await createTenant("cloneonly", "growth");
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Stays behind" }),
    );

    const cloned = capture("project.cloned");
    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant, { includeIssues: false }),
    );

    expect(await issueRepo.countIssues(tenant.org.id, clone.id)).toBe(0);
    expect(cloned[0]).toMatchObject({ projectId: clone.id, issuesCopied: 0 });
  });

  it("copies every live issue of a project larger than one page", async () => {
    const tenant = await createTenant("clonebig", "growth");
    await addIssues(tenant, tenant.project.id, 120);

    const clone = await projectService.cloneProject(tenant.actors.member, cloneInput(tenant));

    const copies = await issueRepo.listAllLiveIssues(tenant.org.id, clone.id);
    expect(copies.map((issue) => issue.number)).toEqual(
      Array.from({ length: 120 }, (_, index) => index + 1),
    );
  });

  it("refuses the whole clone when the copies would exceed the per-project quota", async () => {
    // The free plan allows 100 issues in one project; 101 live issues cannot be copied.
    const tenant = await createTenant("clonequota", "free");
    await addIssues(tenant, tenant.project.id, 101);

    const cloned = capture("project.cloned");

    await expect(
      projectService.cloneProject(tenant.actors.member, cloneInput(tenant)),
    ).rejects.toThrow(/allows 100 issues per project/);

    expect(cloned).toHaveLength(0);
    expect(await projectRepo.findProjectBySlug(tenant.org.id, "release-train")).toBeNull();
    expect(await projectRepo.countProjects(tenant.org.id)).toBe(1);
  });

  it("applies the plan's project quota as creating a project does", async () => {
    // The free plan allows two projects, and createTenant seeds one.
    const tenant = await createTenant("cloneprojquota", "free");

    await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant, { name: "Second copy", slug: "second-copy", key: "SEC" }),
    );

    await expect(
      projectService.cloneProject(
        tenant.actors.member,
        cloneInput(tenant, { name: "Third copy", slug: "third-copy", key: "THI" }),
      ),
    ).rejects.toThrow(/allows 2 projects/);
  });

  it("needs project:create, a source in the caller's workspace, and a live source", async () => {
    const tenant = await createTenant("cloneguards", "growth");
    const other = await createTenant("cloneguards-other", "growth");

    await expect(
      projectService.cloneProject(tenant.actors.viewer, cloneInput(tenant)),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      projectService.cloneProject(other.actors.owner, cloneInput(tenant)),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });

    await expect(
      projectService.cloneProject(tenant.actors.member, cloneInput(tenant)),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("makes the slug unique by suffix, as a created project's slug is", async () => {
    const tenant = await createTenant("cloneslug", "growth");

    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant, { slug: "platform", name: "Platform copy", key: "PCP" }),
    );

    expect(clone.slug).toBe("platform-2");
  });

  it("makes the clone and its copied issues searchable at once", async () => {
    const tenant = await createTenant("clonesearch", "growth");
    const original = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Zebra cutover checklist" }),
    );

    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant, { slug: "cutover", name: "Cutover", key: "CUT" }),
    );
    const [copy] = await issueRepo.listAllLiveIssues(tenant.org.id, clone.id);

    const issueHits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Zebra",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(issueHits.items.map((hit) => hit.id).sort()).toEqual(
      [original.id, copy?.id].sort(),
    );

    const projectHits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Cutover",
      kinds: ["project"],
      limit: 25,
      cursor: null,
    });
    expect(projectHits.items.map((hit) => hit.id)).toEqual([clone.id]);
  });
});

describe("the audit log accepts project.cloned", () => {
  it("validates it as a filter action", () => {
    expect(
      activityFilterSchema.safeParse({
        orgId: "org_filter",
        action: ["project.cloned"],
      }).success,
    ).toBe(true);
  });
});

