/**
 * Writes a clone and its copied issues in one transaction. The project row goes
 * first, so a duplicate key is refused before any copy exists. Copies take
 * numbers 1..n in the order given, start unassigned with no progress, and are
 * authored by `authorId`; only their labels come along.
 */
export async function insertClone(
  input: CreateProjectInput,
  copies: readonly Pick<
    Issue,
    "title" | "description" | "status" | "priority" | "estimate" | "dueAt" | "labelIds"
  >[],
  authorId: UserId,
): Promise<Project> {
  const slug = uniqueSlug(input.slug, await listTakenProjectSlugs(input.orgId));
  const projectId = newId();
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const row = tx
      .insert(projects)
      .values({
        id: projectId,
        orgId: input.orgId,
        name: input.name,
        slug,
        key: input.key,
        description: input.description,
        visibility: input.visibility,
        status: "active",
        leadId: input.leadId,
